module freq_divbyodd(
	input clk, rst_n,
	output clk_div
);
// Parameters
parameter NUM_DIV = 5;
// Registers
reg [2:0] cnt1, cnt2;
reg clk_div1, clk_div2;
// Sequential logic
always @(posedge clk or negedge rst_n) begin
	if(!rst_n) 
	begin
		cnt1 <= 3'd0;
		clk_div1 <= 1'b0;
	end
	else
	begin
		if(cnt1==NUM_DIV-1)
			cnt1 <= 3'd0;
		else
			cnt1 <= cnt1 + 1'b1;
		if(cnt1 < NUM_DIV/2)
			clk_div1 <= 1'b1;
		else
			clk_div1 <= 1'b0;
	end
end
always @(negedge clk or negedge rst_n) begin
	if(!rst_n) 
	begin
		cnt2 <= 3'd0;
		clk_div2 <= 1'b0;
	end
	else
	begin
		if(cnt2==NUM_DIV-1)
			cnt2 <= 3'd0;
		else
			cnt2 <= cnt2 + 1'b1;
		if(cnt2 < NUM_DIV/2)
			clk_div2 <= 1'b1;
		else
			clk_div2 <= 1'b0;
	end
end
// Output assignment
assign clk_div = clk_div1 | clk_div2;
endmodule
